protocolTypes.tsDefinition:
// ── Budget grant answer (correlates on request_id) ────────────────
| {
    type: 'budget_grant_result';
    /** Echo of the `continue_with_budget.request_id` this answers. 1-128 chars, `^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$`. */
    request_id: string;
    /** Tokens actually granted. Integer 0..18446744073709551615. REQUIRED even when refused (the refusal fixture sends 1). */
    additional_tokens: number;
    /** USD actually granted. `minimum: 0`. REQUIRED even when refused (the refusal fixture sends 0.0). */
    additional_cost_usd: number;
    outcome: 'granted' | 'refused';
    /** Present if and only if `outcome === 'refused'`; the schema's allOf FORBIDS it when granted. */
    refusal_reason?: BudgetRefusalReason;
  }

// ── Grant more budget after `budget_exceeded` ─────────────────────
// The schema's `anyOf` (at least one of additional_tokens >= 1 OR
// additional_cost_usd > 0) is NOT expressible here; `buildContinueWithBudget`
// in budgetGrant.ts is the only sanctioned way to construct this value.
| {
    type: 'continue_with_budget';
    /** Host-minted. 1-128 chars, `^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$`. */
    request_id: string;
    /** Integer 0..18446744073709551615. Must be >= 1 when it is the only quantity. */
    additional_tokens?: number;
    /** `minimum: 0`. Must be > 0 (exclusiveMinimum) when it is the only quantity. */
    additional_cost_usd?: number;
  }

// ── Answer a suspension by resume_token (NOT by call_id) ────────────
// Same wire name as the existing WCoreEvent member; different union, no clash.
| {
    type: 'approval_resume';
    resume_token: string;
    approved: boolean;
    /** Free-form answer channel. The schema declares `answer` and allows extra keys. */
    modifications?: { answer?: string; [key: string]: unknown };
  }
